import * as dntShim from "../../_dnt.shims.js";
import { isAbsolute, join } from "../platform/compat/path/index.js";
import { createEvalValidationError, normalizeEvalExamples, normalizeEvalString, } from "./validation.js";
function resolveDatasetPath(baseDir, filePath) {
    return isAbsolute(filePath) ? filePath : join(baseDir, filePath);
}
function parseJsonDataset(text, source) {
    const parsed = JSON.parse(text);
    if (Array.isArray(parsed))
        return parsed;
    if (parsed &&
        typeof parsed === "object" &&
        Array.isArray(parsed.examples)) {
        return parsed.examples;
    }
    throw createEvalValidationError(`${source} must contain an array or an object with examples`);
}
function parseJsonlDataset(text, source) {
    return text
        .split(/\r?\n/)
        .map((line) => line.trim())
        .filter(Boolean)
        .map((line, index) => {
        try {
            return JSON.parse(line);
        }
        catch (error) {
            throw createEvalValidationError(`${source}:${index + 1} must be valid JSON (${error instanceof Error ? error.message : error})`);
        }
    });
}
/** Dataset factories for inline, JSON, and JSONL eval examples. */
export const datasets = {
    inline(examples) {
        const normalized = normalizeEvalExamples(examples, "inline dataset");
        return {
            kind: "inline",
            examples: normalized,
            async load() {
                return normalized.map((example) => ({ ...example }));
            },
        };
    },
    json(path) {
        const datasetPath = normalizeEvalString(path, "JSON dataset path");
        return {
            kind: "json",
            path: datasetPath,
            async load({ baseDir }) {
                const resolvedPath = resolveDatasetPath(baseDir, datasetPath);
                const text = await dntShim.Deno.readTextFile(resolvedPath);
                return normalizeEvalExamples(parseJsonDataset(text, datasetPath), datasetPath);
            },
        };
    },
    jsonl(path) {
        const datasetPath = normalizeEvalString(path, "JSONL dataset path");
        return {
            kind: "jsonl",
            path: datasetPath,
            async load({ baseDir }) {
                const resolvedPath = resolveDatasetPath(baseDir, datasetPath);
                const text = await dntShim.Deno.readTextFile(resolvedPath);
                return normalizeEvalExamples(parseJsonlDataset(text, datasetPath), datasetPath);
            },
        };
    },
};
